"""The stable ``<MIRA_HOME>/bin/mira`` launcher used by Remote-SSH.

A pip install into a conda env or venv puts ``mira`` on PATH only after the env
is activated, usually from ``~/.bashrc``. The non-interactive login shell used by
Remote-SSH (``sh -lc``) does not read that file, so the desktop app looks for
this launcher instead. It calls the env's interpreter directly, so it works
without activation::

    #!/bin/sh
    # Generated by mira (mira remote setup). Do not edit; mira rewrites this file.
    # mira-generated-launcher: 1
    exec '/path/to/env/bin/python' -m mira_engine "$@"

The marker line tells a generated launcher from a user's own file; files
without it are never replaced.
"""

from __future__ import annotations

import contextlib
import importlib.metadata
import logging
import os
import shlex
import site
import stat
import sys
import sysconfig
import tempfile
from dataclasses import dataclass
from pathlib import Path

log = logging.getLogger(__name__)

MARKER = "# mira-generated-launcher: 1"
_MARKER_PREFIX = "# mira-generated-launcher:"
OPT_OUT_ENV = "MIRA_NO_LAUNCHER"
# A generated launcher is a few hundred bytes; anything larger is not ours.
_MAX_READ = 8192
_IS_WINDOWS = os.name == "nt"


class LauncherError(Exception):
    """``setup`` could not write the launcher; ``code`` is the JSON error code."""

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code
        self.message = message


@dataclass(frozen=True)
class LauncherState:
    """What is at the launcher path now."""

    exists: bool
    generated: bool = False
    target: str | None = None

    @property
    def target_ok(self) -> bool:
        return self.target is not None and _is_executable_file(self.target)


def launcher_path() -> Path:
    from mira_engine.config.loader import get_home_dir

    return get_home_dir().expanduser().resolve(strict=False) / "bin" / "mira"


def _sh_quote(value: str) -> str:
    """Single-quote ``value`` for POSIX sh, whatever characters it contains."""
    return "'" + value.replace("'", "'\"'\"'") + "'"


def _frozen() -> bool:
    return bool(getattr(sys, "frozen", False))


def _opted_out() -> bool:
    return os.environ.get(OPT_OUT_ENV, "").strip().lower() in {"1", "true", "yes"}


def render(executable: str) -> str:
    """The launcher script that runs the CLI with interpreter ``executable``."""
    return (
        "#!/bin/sh\n"
        "# Generated by mira (mira remote setup). Do not edit; mira rewrites this file.\n"
        f"{MARKER}\n"
        f'exec {_sh_quote(executable)} -m mira_engine "$@"\n'
    )


def _is_executable_file(path: str) -> bool:
    return os.path.isfile(path) and os.access(path, os.X_OK)


def inspect(path: Path) -> LauncherState:
    """Classify the file at ``path`` without following a symlink there."""
    try:
        info = path.lstat()
    except FileNotFoundError:
        return LauncherState(exists=False)
    # Symlinks, directories and the like are always the user's.
    if not stat.S_ISREG(info.st_mode) or info.st_size > _MAX_READ:
        return LauncherState(exists=True)
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return LauncherState(exists=True)
    lines = text.splitlines()
    if not any(line.startswith(_MARKER_PREFIX) for line in lines):
        return LauncherState(exists=True)
    target = None
    for line in lines:
        if line.startswith("exec "):
            try:
                words = shlex.split(line)
            except ValueError:
                break
            if len(words) >= 2:
                target = words[1]
            break
    return LauncherState(exists=True, generated=True, target=target)


def write(path: Path, content: str) -> None:
    """Write ``content`` to ``path`` atomically with mode 0755."""
    path.parent.mkdir(mode=0o755, parents=True, exist_ok=True)
    fd, tmp = tempfile.mkstemp(dir=path.parent, prefix=".mira.", suffix=".tmp")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            handle.write(content)
            handle.flush()
            os.fchmod(handle.fileno(), 0o755)
            os.fsync(handle.fileno())
        os.replace(tmp, path)
    except BaseException:
        with contextlib.suppress(OSError):
            os.unlink(tmp)
        raise


def _installed_in_interpreter() -> bool:
    """Whether ``<sys.executable> -m mira_engine`` works without this process's env.

    True for a regular or editable pip install into the interpreter's own site
    directories. False when the package is only importable through PYTHONPATH or
    the working directory, or when the interpreter lives inside an app bundle.
    """
    if ".app/Contents/" in sys.executable:
        return False
    try:
        dist = importlib.metadata.distribution("mira-engine")
    except importlib.metadata.PackageNotFoundError:
        return False
    location = Path(str(dist.locate_file(""))).resolve()
    candidates = [sysconfig.get_path("purelib"), sysconfig.get_path("platlib")]
    with contextlib.suppress(Exception):
        candidates.extend(site.getsitepackages())
    if site.ENABLE_USER_SITE:
        with contextlib.suppress(Exception):
            candidates.append(site.getusersitepackages())
    return any(location == Path(c).resolve() for c in candidates if c)


def ensure_launcher() -> None:
    """Create or repair the launcher for this install. Cheap; never raises.

    Runs on every ``mira`` invocation. It writes only when the launcher is
    missing or is a generated one whose interpreter is gone, so a valid launcher
    pointing at another install is left alone (``mira remote setup`` switches it).
    """
    try:
        if _opted_out() or _frozen() or _IS_WINDOWS or not sys.executable:
            return
        path = launcher_path()
        state = inspect(path)
        if state.exists and (not state.generated or state.target_ok):
            return
        if not _installed_in_interpreter():
            log.debug("mira launcher: %s is not a pip install; not writing %s", sys.executable, path)
            return
        write(path, render(sys.executable))
        log.debug("mira launcher: wrote %s -> %s", path, sys.executable)
    except Exception as exc:  # noqa: BLE001 - must never break the CLI
        log.debug("mira launcher: could not ensure the launcher: %s", exc)


def setup() -> Path:
    """(Re)write the launcher for this install, unless a user's file is in the way."""
    if _IS_WINDOWS:
        raise LauncherError("unsupported_platform",
                            "the launcher is a POSIX sh script; Remote-SSH to Windows hosts is not supported")
    if _frozen():
        # The bundled executable runs the `mira-engine` service CLI, not `mira`,
        # so a launcher for it could not serve `mira remote attach`.
        raise LauncherError("unsupported",
                            "this is a bundled engine; install mira with pip on the remote host")
    if not sys.executable:
        raise LauncherError("internal", "the Python interpreter path is unknown")
    path = launcher_path()
    state = inspect(path)
    if state.exists and not state.generated:
        raise LauncherError("launcher_conflict",
                            f"{path} exists and was not generated by mira; move it away and run this again")
    try:
        write(path, render(sys.executable))
    except OSError as exc:
        raise LauncherError("internal", f"cannot write {path}: {exc}") from exc
    return path
